def main():
    net.impair(sandbox="nat-repro",instance="client",nic="eth0",latency_ms=10)
    applied=instance.exec(sandbox="nat-repro",name="client",command="tc qdisc show dev enp5s0")
    net.impair(sandbox="nat-repro",instance="client",nic="eth0",clear=True)
    cleared=instance.exec(sandbox="nat-repro",name="client",command="tc qdisc show dev enp5s0")
    return {"applied":applied,"cleared":cleared}
